-- name: BackofficeListSMS :many
SELECT s.id,t.name AS team_name,s.to_number,s.from_name,s.status,coalesce(s.provider_id,''),coalesce(s.error_message,''),s.created_at FROM sms_messages s JOIN teams t ON t.id=s.team_id WHERE (sqlc.arg(search)::text='' OR t.name ILIKE '%'||sqlc.arg(search)::text||'%' OR s.to_number ILIKE '%'||sqlc.arg(search)::text||'%' OR s.from_name ILIKE '%'||sqlc.arg(search)::text||'%') AND (sqlc.arg(status)::text='' OR s.status=sqlc.arg(status)) ORDER BY s.created_at DESC LIMIT 100;
-- name: BackofficeGetSMS :one
SELECT s.id,t.id AS team_id,t.name AS team_name,coalesce(s.sender_id::text,'')::text AS sender_id,s.to_number,s.from_name,s.body,s.status,coalesce(s.provider_id,'') AS provider_id,coalesce(s.provider_message_id,'') AS provider_message_id,s.segments,coalesce(s.error_message,'') AS error_message,coalesce(s.metadata::text,'{}')::text AS metadata,coalesce(to_char(s.submitted_at,'YYYY-MM-DD HH24:MI'),'')::text AS submitted_at,coalesce(to_char(s.delivered_at,'YYYY-MM-DD HH24:MI'),'')::text AS delivered_at,s.created_at,s.updated_at FROM sms_messages s JOIN teams t ON t.id=s.team_id WHERE s.id=sqlc.arg(id);
